L, NULL), ('dsa-227', 'user-default', 'goal-dsa', 'Basic Calculator II', 'Stack', 'Medium', 'https://leetcode.com/problems/basic-calculator-ii', 30, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-377', 'user-default', 'goal-dsa', 'Combination Sum IV', 'Dynamic Programming', 'Medium', 'https://leetcode.com/problems/combination-sum-iv', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-380', 'user-default', 'goal-dsa', 'Insert Delete GetRandom O(1)', 'Hash Table', 'Medium', 'https://leetcode.com/problems/insert-delete-getrandom-o1', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-435', 'user-default', 'goal-dsa', 'Non-overlapping Intervals', 'Array', 'Medium', 'https://leetcode.com/problems/non-overlapping-intervals', 20, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-336', 'user-default', 'goal-dsa', 'Palindrome Pairs', 'String', 'Hard', 'https://leetcode.com/problems/palindrome-pairs', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-25', 'user-default', 'goal-dsa', 'Reverse Nodes in k-Group', 'Linked List', 'Hard', 'https://leetcode.com/problems/reverse-nodes-in-k-group', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-37', 'user-default', 'goal-dsa', 'Sudoku Solver', 'Matrix', 'Hard', 'https://leetcode.com/problems/sudoku-solver', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-41', 'user-default', 'goal-dsa', 'First Missing Positive', 'Hash Table', 'Hard', 'https://leetcode.com/problems/first-missing-positive', 35, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-51', 'user-default', 'goal-dsa', 'N-Queens', 'Recursion', 'Hard', 'https://leetcode.com/problems/n-queens', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('dsa-632', 'user-default', 'goal-dsa', 'Smallest Range Covering Elements from K Lists', 'Heap', 'Hard', 'https://leetcode.com/problems/smallest-range-covering-elements-from-k-lists', 40, FALSE, NULL, NULL, '2026-11-13T08:21:21.439Z', NULL, FALSE, NULL, NULL), ('mla-1-1-1', 'user-default', 'goal-aws', 'Skill 1.1.1: Extract Data from S3, EBS, EFS, RDS, DynamoDB & OpenSearch', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Think of data extraction as picking the right pipeline for your data warehouse. Amazon S3 is your central unlimited lake. Amazon EBS is a high-speed hard drive attached to a single EC2 instance for fast local scratch files. Amazon EFS is a shared network folder that multiple notebook instances or training nodes can mount at the same time. RDS and DynamoDB hold operational transactional data, while OpenSearch provides fast text search.', 'Exam Tip: For multi-node shared storage choose EFS/FSx; for general datasets choose S3 Fast File mode. Gotcha: Choosing Amazon EBS for distributed multi-node training. EBS CANNOT be shared across multiple instances! Choose EFS or FSx Lustre instead.'), ('mla-1-1-2', 'user-default', 'goal-aws', 'Skill 1.1.2: Storage Decisions Based on Cost, Performance & Compliance', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Storage isn''t one-size-fits-all. S3 Standard is for active training data. S3 Intelligent-Tiering automatically moves data to colder tiers when access drops without performance penalty. S3 Glacier is for compliance archives. For highest compute throughput during deep learning, FSx for Lustre caches directly from S3.', 'Exam Tip: Use Intelligent-Tiering when access patterns are unpredictable to avoid manual lifecycle policies. Gotcha: Picking Glacier for models that retrain weekly. Glacier retrieval latency takes hours and incurs retrieval costs!'), ('mla-1-1-3', 'user-default', 'goal-aws', 'Skill 1.1.3: Troubleshoot and debug data ingestion and storage issues tha', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', FALSE, 'In simple terms, Skill 1.1.3 covers troubleshoot and debug data ingestion and storage issues that involve capacity and scalability. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Collect and store data, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Collect and store data.'), ('mla-1-1-4', 'user-default', 'goal-aws', 'Skill 1.1.4: Real-Time Streaming Ingestion (Kinesis, Flink, Kafka)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'When data arrives in continuous live streams (like user clicks, sensor feeds, or live chat), Amazon Kinesis Data Streams captures millions of events per second with sub-second latency. Kinesis Data Firehose buffers and converts formats before writing to S3. Apache Flink runs stateful real-time window calculations.', 'Exam Tip: If you need immediate streaming feature calculation (<200ms), use Kinesis Streams + Lambda/Flink; if loading to S3/OpenSearch, use Firehose. Gotcha: Confusing Kinesis Streams and Firehose. Firehose CANNOT do custom consumer sub-second push; it buffers data for at least 60 seconds.'), ('mla-1-1-5', 'user-default', 'goal-aws', 'Skill 1.1.5: Ingest from and write by using appropriate data formats (for', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', FALSE, 'In simple terms, Skill 1.1.5 covers ingest from and write by using appropriate data formats (for example, apache parquet, json, csv, orc) based on data access patterns. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Collect and store data, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Collect and store data.'), ('mla-1-1-6', 'user-default', 'goal-aws', 'Skill 1.1.6: Merge data from multiple sources (for example, by using prog', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', FALSE, 'In simple terms, Skill 1.1.6 covers merge data from multiple sources (for example, by using programming techniques, aws glue, apache spark). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Collect and store data, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Collect and store data.')
