INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, completed_at, completed_date, created_at, subtopic, is_important, description, notes)
VALUES ('mla-1-1-7', 'user-default', 'goal-aws', 'Skill 1.1.7: Scalable Vector Databases (OpenSearch, RDS pgvector, S3)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Vector databases store numerical representations (embeddings) of text, code, or images so you can find ''conceptually similar'' items. Amazon OpenSearch Serverless is the primary fully managed vector engine for Bedrock Knowledge Bases. Amazon Aurora/RDS with pgvector is best if you already store your relational data in PostgreSQL.', 'Exam Tip: Bedrock Knowledge Bases defaults to OpenSearch Serverless vector collections for automated indexing. Gotcha: Thinking S3 alone can do vector similarity search. S3 stores the raw documents; a vector database (OpenSearch/pgvector) is required to index embeddings.'), ('mla-1-1-8', 'user-default', 'goal-aws', 'Skill 1.1.8: Ingest and store diverse data types (for example, text, imag', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', FALSE, 'In simple terms, Skill 1.1.8 covers ingest and store diverse data types (for example, text, images, audio) for ai and ml applications. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Collect and store data, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Collect and store data.'), ('mla-1-1-9', 'user-default', 'goal-aws', 'Skill 1.1.9: SageMaker Feature Store (Online vs Offline Store)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.1: Collect and store data', TRUE, 'Feature Store is the single source of truth for computed ML features. The Online Store (built on low-latency storage) serves features in under 10ms for live model inference. The Offline Store (in Amazon S3) maintains historical point-in-time features for batch training and prevents data leakage.', 'Exam Tip: Use the Online Store for sub-10ms inference and the Offline Store for reproducible training sets. Gotcha: Querying the Offline Store during real-time fraud inference. S3 Athena queries take seconds! Query the Online Store for live predictions.'), ('mla-1-2-1', 'user-default', 'goal-aws', 'Skill 1.2.1: Data Transformation (Glue, DataBrew, EMR, Data Wrangler)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'You have multiple tools to clean and transform datasets: SageMaker Data Wrangler is a low-code UI inside Studio to visually clean and export transformations. AWS Glue is a serverless Spark ETL service for scheduled batch processing. AWS Glue DataBrew is a visual spreadsheet tool for business analysts. Amazon EMR is managed Big Data clusters (Hadoop/Spark) for massive custom petabyte workloads.', 'Exam Tip: For serverless scheduled ETL use Glue; for fast visual exploration in SageMaker use Data Wrangler. Gotcha: Choosing EMR when the team wants serverless zero-management ETL. Glue is serverless; EMR requires cluster configuration.'), ('mla-1-2-2', 'user-default', 'goal-aws', 'Skill 1.2.2: Create and manage features by using AWS tools (for example, ', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'In simple terms, Skill 1.2.2 covers create and manage features by using aws tools (for example, sagemaker feature store). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-3', 'user-default', 'goal-aws', 'Skill 1.2.3: Transform streaming data (for example, by using AWS Lambda, ', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', FALSE, 'In simple terms, Skill 1.2.3 covers transform streaming data (for example, by using aws lambda, spark). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-4', 'user-default', 'goal-aws', 'Skill 1.2.4: Perform feature engineering (for example, scaling, standardi', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'In simple terms, Skill 1.2.4 covers perform feature engineering (for example, scaling, standardization, feature splitting, binning, log transformation, normalization). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-5', 'user-default', 'goal-aws', 'Skill 1.2.5: Conﬁgure and use embedding models to transform text and imag', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'In simple terms, Skill 1.2.5 covers conﬁgure and use embedding models to transform text and image data into numerical representations. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-6', 'user-default', 'goal-aws', 'Skill 1.2.6: Apply advanced text pre-processing techniques (for example, ', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', FALSE, 'In simple terms, Skill 1.2.6 covers apply advanced text pre-processing techniques (for example, tokenization, domain- speciﬁc augmentation). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-7', 'user-default', 'goal-aws', 'Skill 1.2.7: Document Preparation for RAG (Chunking & Metadata Extraction)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'RAG (Retrieval Augmented Generation) answers questions using private company docs. Before storing documents in a vector DB, you must slice them into chunks. Fixed-size chunking splits by word count (with overlap so sentences aren''t cut in half). Hierarchical / semantic chunking splits by headers or paragraphs. Metadata (author, section, date) is attached for filtered search.', 'Exam Tip: Always include chunk overlap (typically 10-20%) to preserve conversational and semantic context. Gotcha: Chunking without overlap. Without overlap, questions matching ideas split across chunk boundaries will fail retrieval!'), ('mla-1-2-8', 'user-default', 'goal-aws', 'Skill 1.2.8: Mask, redact, and anonymize data', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', FALSE, 'In simple terms, Skill 1.2.8 covers mask, redact, and anonymize data. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-2-9', 'user-default', 'goal-aws', 'Skill 1.2.9: Prepare data for FM ﬁne-tuning, continuous pre-training, and', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.2: Perform data transformation, feature engineering, and pre-processing', TRUE, 'In simple terms, Skill 1.2.9 covers prepare data for fm ﬁne-tuning, continuous pre-training, and model distillation. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Perform data transformation, feature engineering, and pre-processing, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Perform data transformation, feature engineering, and pre-processing.'), ('mla-1-3-1', 'user-default', 'goal-aws', 'Skill 1.3.1: Validate data quality (for example, by using DataBrew, AWS G', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.3: Validate data quality and manage bias', TRUE, 'In simple terms, Skill 1.3.1 covers validate data quality (for example, by using databrew, aws glue data quality). In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Validate data quality and manage bias, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Validate data quality and manage bias.'), ('mla-1-3-2', 'user-default', 'goal-aws', 'Skill 1.3.2: Label and annotate data', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.3: Validate data quality and manage bias', FALSE, 'In simple terms, Skill 1.3.2 covers label and annotate data. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Validate data quality and manage bias, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Validate data quality and manage bias.'), ('mla-1-3-3', 'user-default', 'goal-aws', 'Skill 1.3.3: Data Bias Mitigation (SageMaker Clarify)', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.3: Validate data quality and manage bias', TRUE, 'Bias happens when a dataset unfairly favors or discriminates against a specific group (e.g. approving loans for one demographic at twice the rate). SageMaker Clarify analyzes pre-training data bias (like Class Imbalance [CI], Difference in Proportions of Labels [DPL]) and post-training model prediction bias (Disparate Impact [DI]).', 'Exam Tip: Use SageMaker Clarify for both pre-training and post-training bias analysis and model explainability (SHAP). Gotcha: Assuming Clarify automatically modifies data to fix bias. Clarify DETECTS and METRICIZES bias; you must apply resampling or reweighting!'), ('mla-1-3-4', 'user-default', 'goal-aws', 'Skill 1.3.4: Optimize multimodal data distributions by applying bias metr', 'Domain 1: Data Preparation for ML & AI', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 20, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.3: Validate data quality and manage bias', FALSE, 'In simple terms, Skill 1.3.4 covers optimize multimodal data distributions by applying bias metrics across numeric, text, and image assets. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Validate data quality and manage bias, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Validate data quality and manage bias.'), ('mla-1-3-5', 'user-default', 'goal-aws', 'Skill 1.3.5: Resolve class imbalance in numeric, text, and image datasets', 'Domain 1: Data Preparation for ML & AI', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 25, FALSE, NULL, NULL, '2026-11-14T14:47:00.125Z', 'Task 1.3: Validate data quality and manage bias', TRUE, 'In simple terms, Skill 1.3.5 covers resolve class imbalance in numeric, text, and image datasets. In production machine learning and generative AI workflows on AWS, this capability ensures high reliability, seamless automation, and optimal compute efficiency to ace the MLA-C02 exam.', 'Exam Tip: For Validate data quality and manage bias, prioritize serverless and managed integrations. Gotcha: Selecting generic open-source EC2 setups instead of AWS native tools for Validate data quality and manage bias.'), ('mla-1-3-6', 'user-default', 'goal-